        _Star_1_Position    ("Star 1 Position", Vector) = (0.5, 0.3, 0.8, 0)
        _Star_1_Color       ("Star 1 Color", Color) = (1, 1, 1, 1)
        _Star_1_Size        ("Star 1 Size", Float) = 0
        _Star_1_Falloff     ("Star 1 Falloff", Float) = 2000000
        _Star_2_Position    ("Star 2 Position", Vector) = (-0.6, 0.4, 0.7, 0)
        _Star_2_Color       ("Star 2 Color", Color) = (1, 1, 1, 1)
