        _Star_3_Position    ("Star 3 Position", Vector) = (0.3, -0.6, 0.7, 0)
        _Star_3_Color       ("Star 3 Color", Color) = (1, 1, 1, 1)
        _Star_3_Size        ("Star 3 Size", Float) = 0
        _Star_3_Falloff     ("Star 3 Falloff", Float) = 1500000
        _Star_4_Position    ("Star 4 Position", Vector) = (-0.3, -0.2, 0.9, 0)
        _Star_4_Color       ("Star 4 Color", Color) = (1, 1, 1, 1)
        _Star_4_Size        ("Star 4 Size", Float) = 0
